import type { ReactNode } from 'react';
import './scanline-sweep.css';

export interface ScanlineSweepProps {
  /** The diagram being scanned. */
  children: ReactNode;
  /** Shown when the scan finishes, for example "No faults found". */
  result: string;
  /** Change this value to scan again. */
  playKey?: number | string;
  /** One pass, in milliseconds. */
  duration?: number;
  className?: string;
}

/**
 * A single line passes once down a diagram, then a small result label
 * settles in. It runs one pass per `playKey`, never loops, and with reduced
 * motion the result appears right away.
 */
export function ScanlineSweep({
  children,
  result,
  playKey = 0,
  duration = 1800,
  className = '',
}: ScanlineSweepProps) {
  return (
    <div
      key={playKey}
      className={`mg-scan ${className}`}
      style={{ ['--mg-duration' as string]: `${duration}ms` }}
    >
      {children}
      <span className='mg-scan__line' aria-hidden='true' />
      <span className='mg-scan__result' role='status'>
        ✓ {result}
      </span>
    </div>
  );
}

.mg-scan {
  position: relative;
  overflow: hidden;
  border-radius: 14px;
  background: var(--mg-raised, #262626);
}

.mg-scan > :first-child {
  display: block;
  width: 100%;
  height: auto;
}

.mg-scan__line {
  position: absolute;
  right: 0;
  left: 0;
  top: 0;
  height: 2px;
  background: var(--mg-accent, #eaf2fb);
  box-shadow: 0 0 12px 2px rgba(220, 233, 247, 0.45);
  opacity: 0;
  animation: mg-scan-pass var(--mg-duration) cubic-bezier(0.4, 0, 0.6, 1)
    forwards;
}

.mg-scan__result {
  position: absolute;
  right: 10px;
  bottom: 10px;
  padding: 4px 10px;
  border-radius: 6px;
  background: var(--mg-accent, #eaf2fb);
  color: #080808;
  font-size: 13px;
  font-weight: 700;
  opacity: 0;
  animation: mg-scan-done 260ms ease-out forwards;
  animation-delay: var(--mg-duration);
}

@keyframes mg-scan-pass {
  0% {
    top: 0;
    opacity: 1;
  }
  95% {
    opacity: 1;
  }
  100% {
    top: calc(100% - 2px);
    opacity: 0;
  }
}

@keyframes mg-scan-done {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-scan__line {
    display: none;
  }
  .mg-scan__result {
    opacity: 1;
    animation: none;
  }
}
